#include <WiFi.h>
#include <WebServer.h>

// بيانات شبكة الواي فاي بتاعتك
const char* ssid = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";

// بنز المحركات عبر L298N للـ ESP32 v3
const int ENA = 14;
const int IN1 = 12;
const int IN2 = 13;
const int ENB = 25;
const int IN3 = 32;
const int IN4 = 33;

WebServer server(80);

void setup() {
  Serial.begin(115200);

  // إعداد بنز المحركات
  pinMode(ENA, OUTPUT);
  pinMode(ENB, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);

  analogWrite(ENA, 200);
  analogWrite(ENB, 200);

  // الاتصال بالواي فاي
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println("");
  Serial.println("تم الاتصال بالواي فاي بنجاح!");
  Serial.print("IP Address: ");
  Serial.println(WiFi.localIP());

  // إعداد مسارات الويب للتحكم
  server.on("/forward", []() {
    moveForward();
    server.send(200, "text/plain; charset=utf-8", "الروبوت يتحرك للأمام الآن");
  });

  server.on("/stop", []() {
    stopRobot();
    server.send(200, "text/plain; charset=utf-8", "تم إيقاف الروبوت");
  });

  server.begin();
}

void loop() {
  server.handleClient();
}

void moveForward() {
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);
}

void stopRobot() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, LOW);
}
